// 前端：静态化 + 限流
// - 商品详情页静态化
// - 前端限流：限制请求频率
// - 验证码：防止自动化脚本

// 网关层：流量控制
// - 请求路由和负载均衡
// - 黑白名单控制
// - 基于用户的限流

// 应用层：业务处理
@Service
public class SeckillService {

    @Autowired
    private RedisService redisService;

    @Autowired
    private OrderService orderService;

    public SeckillResult seckill(Long userId, Long productId) {

        // 1. 基础校验
        if (!isValidRequest(userId, productId)) {
            return SeckillResult.INVALID_REQUEST;
        }

        // 2. 库存预扣（Redis）
        Long stock = redisService.decrStock(productId);
        if (stock < 0) {
            return SeckillResult.OUT_OF_STOCK;
        }

        // 3. 发送异步消息
        messageQueue.sendSeckillMessage(userId, productId);

        return SeckillResult.PROCESSING;
    }
}

// 消息消费者：异步处理
@Component
public class SeckillMessageConsumer {

    @RabbitListener(queues = "seckill.queue")
    public void processSeckill(SeckillMessage message) {
        try {
            // 1. 重复请求检查
            if (isDuplicateRequest(message)) {
                return;
            }

            // 2. 数据库扣减库存
            boolean success = inventoryService.deductStock(message.getProductId());
            if (!success) {
                // 库存不足，回滚Redis
                redisService.incrStock(message.getProductId());
                return;
            }

            // 3. 创建订单
            orderService.createOrder(message);

        } catch (Exception e) {
            // 异常处理：记录日志，人工干预
            log.error("秒杀处理失败", e);
        }
    }
}

// 数据库层：优化设计
// - 秒杀商品表：product_seckill
// - 库存表：使用乐观锁version字段
// - 订单表：分表存储
// - 索引设计：user_product唯一索引防止重复购买
```

